        { id: 'w2', kind: 'twy', name: '<img src=x onerror=alert(1)>' + 'Z'.repeat(40), line: [[2.36, 48.73], [2.37, 48.74]] },
        { id: 'w3', kind: 'twy', name: 'one point', line: [[2.36, 48.73]] },
