        r = RJ.REGISTRY[('route', 'import-rad')][0](RJ.Job('route', 'import-rad', {}, author='TST'), {'dry': False, 'books': [{'name': 'RAD_2611_v1_0.xlsx', 'size': size}]}, ctx)
