        (vdir / 'index.json').write_text(json.dumps({'schema': 2, 'aerodromes': [{'ad': 'LFZZ', 'points': 1, 'routes': 0, 'notes': 0, 'unmatched': 0, 'analysis': None, 'cycle': cyc_old}]}), encoding='utf-8')
        b = V.build(RJ.Job('vfr', 'build', {}), {'cycle': cyc}, ctx)
