        'idx = {"schema": 1, "model": "gfs", "run": 1_799_990_000, "built": 1_700_000_000, "step": 5, "times": t, "files": names, "altFiles": [x.replace(".json", "-alt.json") for x in names]}\n'
        'json.dump(idx, open(os.path.join(out, "index.json"), "w"))\n'
