@case('K202', 'French aircraft registry (SOG-0270, Sécurisation rules): only the five whitelisted columns are kept, found by their header NAME; the original is never kept; no owner name or address anywhere (derived file, answer, error, upload answer); bounds refuse; `aircraft/registry` finds a type from a registration and registrations of a type', 'K', static=True,
      rule='SOG-0270 (12 Nov 2026) with the review of Sécurisation: the registry export has 13 columns, 8 of them third parties (owner, tenant, mortgage creditor, seizing person, and their addresses). tools/registry_fr.py keeps IMMATRICULATION, CONSTRUCTEUR, MODELE, NUMERO_SERIE, AERODROME_ATTACHE by header name, in data/local/registry/fr_immat.json (never in the data repository); the original is not kept (upload: the temporary file is dropped at once); refusals say a code, never a line; bounds: 40 MB, 300 000 rows, 4 096 characters per physical line, 80 per field, a registration shape. The verb `aircraft/registry` is read-only: { reg } gives the type of a registration, { type: « cessna 172 » } the registrations of a type. A fake file with a canary owner name and address is used: the canary must be found NOWHERE.')
def k202(c):
    import io
    import json
    import sys
    import tempfile
    from pathlib import Path
    RJ = _regen()
    sys.path.insert(0, str(ROOT / 'tools'))
    import registry_fr
    head = 'IMMATRICULATION;CONSTRUCTEUR;MODELE;NUMERO_SERIE;AERODROME_ATTACHE;PROPRIETAIRE;ADRESSE_PROPRIETAIRE;LOCATAIRE;ADRESSE_LOCATAIRE;CREANCIER_HYPOTHEQUE;ADRESSE_CREANCIER;PERSONNE_SAISISSANTE;ADRESSE_PERSONNE_SAISISSANTE'
    canary = 'CANARYDUPONT'
    lines = [head,
             f'F-BHHH;CESSNA;172 N;17270001;PARIS-SACLAY;{canary} JEAN;12 RUE {canary};;;;;;',
             f'F-GXES;ROBIN AVIATION;DR 400/140B;2345;;{canary} SARL;{canary} ZA;{canary} LOC;x;;;;',
             f'F-HTOO;SOCATA;TB 20;77;TOUSSUS;{canary};adr;;;;;;',
             f'XX;BAD;ROW;1;;{canary};;;;;;;',
             f'F-BHHH;CESSNA;172 N;17270001;PARIS-SACLAY;{canary} AUTRE;adr;;;;;;']
    with tempfile.TemporaryDirectory(ignore_cleanup_errors=True) as td:
        td = Path(td)
        src = td / 'export.csv'
        src.write_bytes(('﻿' + '\n'.join(lines) + '\n').encode('utf-8'))
        out = td / 'data' / 'local' / 'registry'
        c.eq((registry_fr.sniff(src.read_bytes()[:4096]), registry_fr.sniff(b'a,b,c\n1,2,3\n'), registry_fr.sniff(b'PK\x03\x04')), (True, False, False), 'the file is recognised by its header, not by its name', what='sniff')
        keep = registry_fr.MIN_MAKER
        registry_fr.MIN_MAKER = 1             # this fixture has one aircraft per maker: the threshold is tested in K205
        res = registry_fr.derive(str(src), str(out), today=1794000000)
        registry_fr.MIN_MAKER = 5
        doc = json.loads((out / 'fr_immat.json').read_text(encoding='utf-8'))
        c.eq((res['rows'], res['skipped'], doc['columns'], doc['rows'][0]), (3, 1, list(registry_fr.WHITELIST), ['F-BHHH', 'CESSNA', '172 N', '17270001', 'PARIS-SACLAY']),
             'three distinct aircraft kept (the duplicate registration line with another owner is one row; the badly formed registration is counted, not kept); five columns only, by header name', what='derive')
        c.ok(canary not in (out / 'fr_immat.json').read_text(encoding='utf-8') and canary not in json.dumps(res), 'canary', 'no owner name or address in the derived file nor in the answer')
        c.eq(sorted(p.name for p in td.rglob('*') if p.is_file()), ['export.csv', 'fr_immat.json'], 'only the derived file is written (the test keeps its own fake source: the upload drops it)', what='files')
        # the verb
        fn, check = RJ.REGISTRY[('aircraft', 'registry')]
        ctx = {'data': str(td / 'data')}
        run = lambda **a: fn(RJ.Job('aircraft', 'registry', {}), check(a), ctx)
        r = run(reg='fbhhh')
        t = run(type='cessna 172')
        e = run(type='robin')
        c.eq(([(x['reg'], x['maker'], x['model'], x['base']) for x in r['rows']], r['source'], [x['reg'] for x in t['rows']], [x['reg'] for x in e['rows']], 'owner' in json.dumps(r).lower() or canary in json.dumps([r, t, e])),
             ([('F-BHHH', 'CESSNA', '172 N', 'PARIS-SACLAY')], registry_fr.CREDIT, ['F-BHHH'], ['F-GXES'], False), 'a registration (with or without the dash) gives its type; a type gives its registrations; the answer carries the credit and no third party', what='lookup')
        c.eq((check({}), check({'reg': 'x'}), check({'reg': 'F-BHHH', 'owner': 1}), check({'type': 'cessna', 'limit': 999}), check({'reg': 'F-BHHH'})), (None, None, None, None, {'reg': 'F-BHHH', 'limit': 50}), 'strict arguments: reg or type, nothing else, a bounded limit', what='check')
        none = fn(RJ.Job('aircraft', 'registry', {}), check({'reg': 'F-BHHH'}), {'data': str(td / 'other')})
        c.eq((none['rows'], none.get('absent')), ([], True), 'no registry on the workstation: empty and said', what='absent')
        # bounds and refusals: a code, never a line
        long = td / 'long.csv'
        long.write_text(head + '\n' + 'F-AAAA;X;' + 'M' * 5000 + canary + ';1;\n', encoding='utf-8')
        nohead = td / 'nohead.csv'
        nohead.write_text(f'A;B;C\n1;2;{canary}\n', encoding='utf-8')
        codes = []
        for f in (long, nohead, td / 'missing.csv'):
            try:
                registry_fr.derive(str(f), str(out))
                codes.append('derived')
            except registry_fr.RegistryError as ex:
                codes.append((ex.code, canary in str(ex)))
        c.eq(codes, [('line', False), ('headers', False), ('read', False)], 'a line over 4 096 characters, a file without the registry header, a missing file: refused with a code, never a content of the file', what='refusals')


@case('K203', 'The upload recognises the registry export by its header (whatever its name), says it will be DERIVED (never kept), and `base/cycle.local` lists the derived registry with its date (SOG-0270)', 'K', static=True,
      rule='SOG-0270: the user drops `export.csv` (or « export (1).csv »); the upload recognises it by the header (IMMATRICULATION; CONSTRUCTEUR; MODELE…) and answers source `registry_fr` with `derive` — the handler derives the five-column file into data/local/registry/ and drops the original at once (the answer carries the row count, never a row). A CSV without the header is refused as any other unknown file. `base/cycle.local` gets the line « Registre français des immatriculations (DGAC) » with the date of the derived file.')
def k203(c):
    import datetime
    import json
    import sys
    import tempfile
    from pathlib import Path
    RJ = _regen()
    sys.path.insert(0, str(ROOT / 'tools'))
    import base_upload
    import registry_fr
    with tempfile.TemporaryDirectory(ignore_cleanup_errors=True) as td:
        td = Path(td)
        ok = td / 'a.csv'
        ok.write_text('IMMATRICULATION;CONSTRUCTEUR;MODELE;NUMERO_SERIE;AERODROME_ATTACHE;PROPRIETAIRE\nF-BHHH;CESSNA;172;1;X;Y\n', encoding='utf-8')
        r = base_upload.recognise(str(ok), 'export (1).csv')
        c.eq((r['source'], r.get('derive'), r['name']), ('registry_fr', True, registry_fr.OUT_NAME), 'recognised by its header: derived, not kept', what='recognise')
        bad = td / 'b.csv'
        bad.write_text('A;B;C\n1;2;3\n', encoding='utf-8')
        try:
            base_upload.recognise(str(bad), 'export.csv')
            other = 'recognised'
        except base_upload.Refused as e:
            other = e.reason
        c.ok(other != 'recognised' and other != 'registry_fr', other, 'a CSV without the registry header is refused like any unknown file')
        data = td / 'data'
        (data / 'sia').mkdir(parents=True)
        registry_fr.derive(str(ok), str(data / 'local' / 'registry'))
        fn, check = RJ.REGISTRY[('base', 'cycle')]
        res = fn(RJ.Job('base', 'cycle', {}), check({}), {'data': str(data), 'downloads': lambda: [], 'today': datetime.date(2026, 11, 12)})
        loc = [x for x in res['local'] if x['id'] == 'registry_fr']
        c.eq((len(loc), loc and len(loc[0]['label']), loc and bool(loc[0]['at'])), (1, 4, True), 'base/cycle.local lists the registry with its date', what='local')


@case('K204', 'RF arcs through aerodb itself (SOG-0248, LFST RWY 23 path): the centre is resolved like an en-route point, the arc developed before the end point and the record served once it agrees with the page; kept in doubt when the centre does not resolve or the arc does not fit; fixesOf() never returns an arc point, pathOf() returns all of them', 'K', tags=('aerodb',), phone=False,
      rule='Ergonomist 12 Nov 2026: the Python build path (K200) cannot place the centre ST500 of LFST RWY 23 (not on the DATA_01 page): it is resolved by aerodb at read time (placeProc → developRf). Invented positions: ST420 and ST430 as on the page, the centre at 2.47 NM of both ends (arc 7.02 NM for 7.1 printed). The record comes in doubt `rf-arc`; aerodb resolves the centre in the zone, develops the arc (a point every 5° at most, `arc: true`, `id` null, before ST430), checks it against the printed radius and arc length and, when it fits and `rf-arc` was the only doubt, serves it as check (the default list then has it). Centre absent from the zone, or a printed radius that does not fit: the record stays in doubt, no chord. AeroDBProcedures.fixesOf (named fixes: the points list, locks, time over zone, FMS / PLN export) never returns an arc point; pathOf (the Map, the profile, distances) returns the whole path.')
def k204(c):
    c.page.goto(f'{c.base}/frame/aerodb/test/procedures.html', wait_until='load')
    r = c.js("""async () => {
      const kinds = ['meta', 'aerodromes', 'navaids', 'points', 'vrp', 'airways'], z = 'fr', cycle = '2026-10-29';
      const mk = async (centre, radius) => {
        const rec = { id: 'LFST.APP.RNPRWY23.RW23', icao: 'LFST', kind: 'APP', name: 'RNP RWY 23', runways: ['23'], transition: null, status: 'doubt', doubt: 'rf-arc', source: { kind: 'eaip', file: 'AD_2_LFST_DATA_RWY23_FNA_RNP_CODE.pdf' }, points: [
          { seq: 1, id: 'ST420', lat: 48.505417, lon: 7.571917, leg: 'TF', alt: null },
          { seq: 2, id: 'ST430', lat: 48.559528, lon: 7.480167, leg: 'RF', alt: null, center: 'ST500', radius, nm: 7.1, turn: 'R' },
          { seq: 3, id: 'STS26', lat: 48.62, lon: 7.40, leg: 'TF', alt: null }] };
        const file = { schema: 1, icao: 'LFST', cycle, updated_at: '2026-11-01T00:00:00Z', procedures: [rec] };
        const pts = centre ? [{ id: 'ST500', lat: 48.537057, lon: 7.532228 }] : [{ id: 'XXXXX', lat: 48.5, lon: 7.5 }];
        const files = { ...Object.fromEntries(kinds.map(k => [`sia/base/${z}/${cycle}/${k}.json`, k === 'meta' ? { schema: 2, zone: z, cycle, kind: 'meta', parserVersion: 27, data: {} } : { schema: 2, zone: z, cycle, kind: k, data: k === 'points' ? pts : [] }])),
          'sia/base/index.json': { schema: 2, kind: 'index', zones: { [z]: { cycle, prefixes: ['LF'], kb: {} } } },
          'proc/manual/LFST.json': file, 'proc/manual/index.json': { schema: 1, aerodromes: { LFST: { SID: 0, STAR: 0, APP: 1, status: 'check' } } } };
        const db = AeroDB.create({ reader: { read: async p => p in files ? { value: files[p], rev: 'r' } : null, list: async prefix => Object.keys(files).filter(p => p.startsWith(prefix)), watch: () => () => {} }, lnmperf: false, now: () => Date.parse('2026-11-10T12:00:00Z') });
        const all = await db.procedures('LFST', { doubt: true }), dflt = await db.procedures('LFST');
        const r = all.find(x => x.id === rec.id);
        return { status: r && r.status, doubt: r && r.doubt, ids: r && r.points.map(p => p.id), arcs: r ? r.points.filter(p => p.arc).length : -1, arcOk: r ? r.points.filter(p => p.arc).every(p => p.id === null && p.leg === 'RF' && Number.isFinite(p.lat)) : false,
          gaps: r && r.points.find(p => p.id === 'ST430').arcGaps, inDefault: dflt.some(x => x.id === rec.id), pts: r && r.points };
      };
      const ok = await mk(true, 2.47), noCentre = await mk(false, 2.47), badRadius = await mk(true, 3.5);
      const P = window.AeroDBProcedures || (await import('/frame/aerodb/procedures.js'), window.AeroDBProcedures);
      return { ok: { ...ok, pts: undefined, ids: ok.ids.filter(Boolean), order: ok.ids.map(i => i === null ? 'a' : i).join(',').replace(/(a,)+/, 'a,') }, noCentre: { ...noCentre, pts: undefined }, badRadius: { status: badRadius.status, arcs: badRadius.arcs, gaps: badRadius.gaps && badRadius.gaps.length, inDefault: badRadius.inDefault },
        fixes: P.fixesOf(ok.pts).map(p => p.id), pathLen: P.pathOf(ok.pts).length, total: ok.pts.length, nullIds: P.fixesOf(ok.pts).some(p => !p.id || p.arc) }; }""")
    ok = r['ok']
    c.eq((ok['status'], ok['doubt'], ok['arcs'] >= 20, ok['arcOk'], ok['gaps'], ok['inDefault'], ok['order']), ('check', None, True, True, None, True, 'ST420,a,ST430,STS26'),
         'centre resolved in the zone: the arc is developed (20+ points, id null, leg RF) BETWEEN ST420 and ST430, no gap against the page, the doubt `rf-arc` is lifted and the default list has the procedure', what='lifted')
    c.eq((r['noCentre']['status'], r['noCentre']['doubt'], r['noCentre']['arcs'], r['noCentre']['inDefault']), ('doubt', 'rf-arc', 0, False), 'centre that does not resolve: still in doubt `rf-arc`, no arc point, no chord, hidden from the default list', what='no centre')
    c.eq((r['badRadius']['status'], r['badRadius']['arcs'] >= 20, r['badRadius']['gaps'] >= 1, r['badRadius']['inDefault']), ('doubt', True, True, False), 'a printed radius that does not fit the positions: the arc is drawn but the gaps are said (arcGaps) and the procedure stays in doubt', what='gap')
    c.eq((r['fixes'], r['pathLen'] == r['total'], r['nullIds']), (['ST420', 'ST430', 'STS26'], True, False), 'fixesOf: only the named fixes (never an arc point, never an id null); pathOf: every positioned point, arcs included', what='consumers')


@case('K205', 'Registry: a CONSTRUCTEUR shared by fewer than 10 aircraft is left EMPTY (amateur builders are persons: « NOM PRÉNOM »), never written nor answered; a duplicated whitelisted header is refused (SOG-0270, Sécurisation review of 7c6ec44ae)', 'K', static=True,
      rule='Sécurisation 12 Nov 2026 (proved on the real export, counts only): 2 276 rows carry a CONSTRUCTEUR value that appears once; of 14 sampled values in two or three words nearly all are « SURNAME FIRSTNAME » (amateur builders): personal names in a whitelisted column. k-anonymity on the content: a maker is kept only when at least MIN_MAKER = 10 distinct (5 first; raised to 10 on 12 Nov: about ten prolific amateur builders with 5 to 8 aircraft are persons on the real export) distinct aircraft of the file carry it (counted before writing), else empty (« constructeur non précisé »): 462 makers and 38 910 of 43 260 rows keep theirs on the real file. A header where a whitelisted name appears twice is refused (`headers`): `index` would take the first, a third-party column renamed before the real one would pass. The case: 10 CESSNA + 2 « DUPONT JEAN »: the derived file and the verb have CESSNA, never DUPONT; red without the threshold.')
def k205(c):
    import json
    import sys
    import tempfile
    from pathlib import Path
    RJ = _regen()
    sys.path.insert(0, str(ROOT / 'tools'))
    import registry_fr
    head = 'IMMATRICULATION;CONSTRUCTEUR;MODELE;NUMERO_SERIE;AERODROME_ATTACHE;PROPRIETAIRE'
    rows = [f'F-GA{n}{n};CESSNA;172 N;{n};X;P' for n in 'ABCDEFGHIJ'] + ['F-PZZZ;DUPONT JEAN;MON AVION 1;9;Y;P', 'F-PYYY;DUPONT JEAN;MON AVION 1;10;Y;P']
    with tempfile.TemporaryDirectory(ignore_cleanup_errors=True) as td:
        td = Path(td)
        src = td / 'export.csv'
        src.write_text('\n'.join([head] + rows) + '\n', encoding='utf-8')
        out = td / 'data' / 'local' / 'registry'
        res = registry_fr.derive(str(src), str(out))
        raw = (out / 'fr_immat.json').read_text(encoding='utf-8')
        doc = json.loads(raw)
        c.eq((res['rows'], res['makerBlanked'], sorted({r[1] for r in doc['rows']}), 'DUPONT' in raw), (12, 2, ['', 'CESSNA'], False), '10 CESSNA kept, the two « DUPONT JEAN » rows keep their registration and model but an EMPTY maker: the name is nowhere in the derived file', what='threshold')
        fn, check = RJ.REGISTRY[('aircraft', 'registry')]
        ctx = {'data': str(td / 'data')}
        r = fn(RJ.Job('aircraft', 'registry', {}), check({'reg': 'F-PZZZ'}), ctx)
        t = fn(RJ.Job('aircraft', 'registry', {}), check({'type': 'cessna'}), ctx)
        c.eq(([(x['reg'], x['maker'], x['model']) for x in r['rows']], len(t['rows']), 'DUPONT' in json.dumps([r, t])), ([('F-PZZZ', '', 'MON AVION 1')], 10, False), 'the verb: the amateur-built aircraft is found by registration with no maker; the type search « cessna » finds the ten; no name in any answer', what='verb')
        dup = td / 'dup.csv'
        dup.write_text('IMMATRICULATION;CONSTRUCTEUR;MODELE;NUMERO_SERIE;AERODROME_ATTACHE;MODELE\nF-AAAA;X;Y;1;Z;TIERS\n', encoding='utf-8')
        try:
            registry_fr.derive(str(dup), str(out))
            code = 'derived'
        except registry_fr.RegistryError as e:
            code = e.code
        c.eq(code, 'headers', 'a whitelisted header name present twice: refused (code only)', what='duplicate header')


@case('K206', 'Catalogue for the country sheet (Réglages, Data screen redesign): `steps.why` says the KNOWN reason a source is taken by hand (six sources, ×4 languages; none for a source without a known reason) and `partNamesOf(zone)` names the parts of a zone that is not in one piece (PT: continent, Madère, Açores), null otherwise', 'K', tags=('aerodb',), phone=False,
      rule='Ergonomist 12 Nov 2026 (Réglages asks for the fields the redesigned country sheet expects): (2) `partNamesOf` — « PT · 3 zones : continent, Madère, Açores »: only the zones whose parts are KNOWN (the rings of shared/carto/aero_zones_geo.js grouped by proximity: Portugal = mainland, Madeira (32.7°N, 17°W), the Azores; Spain = mainland + Balearics, Canary Islands; Netherlands + Bonaire; Denmark + Bornholm; Norway with Jan Mayen, Bjørnøya, Svalbard; the United States contiguous, Alaska with the Aleutians, Hawaii), nothing guessed; (3) `steps.why` for SIA (the basket), DIRCAM (site down, file in the SIA CD), UK Mil (SSLEOF, no publication for about a year), NAV Portugal (published by editions, not by cycle), FAA (HTTP 403 sometimes): a source with no known reason has no line.')
def k206(c):
    c.page.goto(f'{c.base}/frame/aerodb/test/catalogue.html', wait_until='load')
    r = c.js("""() => { const C = AeroCatalogue, ids = C.SOURCES.filter(s => s.steps).map(s => s.id);
      const why = Object.fromEntries(ids.map(i => [i, C.stepsOf(i, '2612').why || null]));
      return { why, parts: Object.fromEntries(['pt', 'es', 'us', 'no', 'fr', 'de', 'xx'].map(z => [z, C.partNamesOf(z)])), ptFr: C.partNamesOf('PT').map(n => n[0]), mutate: (() => { const a = C.partNamesOf('pt'); a[0][0] = 'x'; return C.partNamesOf('pt')[0][0]; })() }; }""")
    withWhy = sorted(k for k, v in r['why'].items() if v)
    # SOG-0368 (94b18b2b4): Iceland (Avians) has its known reason — the site does not answer or refuses the launcher, the pages of the eAIP are saved by hand — in four languages: the sixth
    c.eq(withWhy, ['adds', 'avians', 'dircam', 'navpt', 'sia', 'ukmil'], 'the six sources with a known reason have `why` (Avians since SOG-0368); the others (NATS, LFV, Naviair, NAV CANADA, EUROCONTROL, VAC) have none', what='which')
    c.ok(all(isinstance(v, list) and len(v) == 4 and all(isinstance(t, str) and len(t.strip()) > 20 for t in v) for v in r['why'].values() if v), str(r['why'])[:200], 'each reason in four languages')
    c.eq((r['ptFr'], r['parts']['fr'], r['parts']['de'], r['parts']['xx'], len(r['parts']['pt']), len(r['parts']['es']), len(r['parts']['us']), len(r['parts']['no'])), (['continent', 'Madère', 'Açores'], None, None, None, 3, 2, 3, 4),
         'PT: continent, Madère, Açores; a zone in one piece or with unnamed parts (DE, FR with its overseas, an unknown code): null', what='parts')
    c.ok(all(len(n) == 4 for z in ('pt', 'es', 'us', 'no') for n in r['parts'][z]) and r['mutate'] == 'continent', str(r['mutate']), 'each part name in four languages; the table cannot be modified from outside (copies)')


