        built = lambda i, cycle: ((data / 'sia' / 'vfr').mkdir(parents=True, exist_ok=True), (data / 'sia' / 'vfr' / f'{i}.json').write_text(json.dumps({'schema': 2, 'ad': i, 'source': {'file': f'AD-2.{i}.pdf', 'cycle': cycle}}), encoding='utf-8'))
