@case('K238', 'Route engine, the loaded context is kept from one calculation to the next (SOG-0296): the second calculation reads no file of the base; a changed, added or removed file (base, procedure, RAD, NAT) rebuilds it; two contexts at most; none kept past its idle time; the result is the same warm as cold', 'K', static=True,
      rule='Ergonomist 13 Nov 2026 (SOG-0296, Features SOG\'s measure): LFPO → EIDW took 3.6 to 4.5 s on the workstation, of which 1.7 s to load the context (507 JSON files and the engine\'s init) at EVERY request, then the routing graph rebuilt each time; nothing was kept. plan.context keeps (Nav, Rad) under the key (root, data folder, RAD, FRA, date of the flight) as long as the FINGERPRINT of the files it read (path, modification time, size of sia/base, proc, the NAT layer and the two books) does not change: a rebuilt base, a procedure read again, an imported book or a new NAT message gives another fingerprint and the context is rebuilt. Bounds: 2 contexts, 1 hour idle. Measured on the workstation: cold 2.4 s, the same pair warm 0.35 s, another pair warm 1.4 s (target: under 2 s), the fingerprint 11 ms')
def k238(c):
    import gzip
    import json
    import os
    import tempfile
    RJ = _regen()
    import route_fixture as RF
    from route_engine import import_books as I
    from route_engine import nav_data
    from route_engine import plan as P
    fn = RJ.REGISTRY[('route', 'compute')][0]
    loads = []
    orig = nav_data.load
    nav_data.load = lambda path: (loads.append(str(path)), orig(path))[1]
    from route_engine import results_cache as RC
    RC.ENABLED = False                      # this case is about the CONTEXT: with the results kept, the second call would not even ask for it (K266 is the results)
    try:
        with tempfile.TemporaryDirectory(ignore_cleanup_errors=True) as td:
            data = os.path.join(td, 'data')
            os.makedirs(data)
            RF.make_base(data)
            rad = os.path.join(td, 'RAD_2611_v1_0.xlsx')
            RF.write_xlsx(rad, RF.rad_sheets())
            I.write(os.path.join(data, 'route', 'rad.json.gz'), I.merge([], [I.read_book(rad)[1]]))
            with gzip.open(os.path.join(data, 'route', 'fra.json.gz'), 'wt', encoding='utf-8') as f:
                json.dump([], f)
            ctx = {'data': data, 'secrets': td}
            P.drop_contexts()
            stats = lambda: (P.CONTEXT_STATS['built'], P.CONTEXT_STATS['reused'])

            def run(date='2026-11-10T12:00'):
                before = len(loads)
                r = fn(RJ.Job('route', 'compute', {}, author='TST'), {'dep': 'LFPO', 'arr': 'EIDW', 'fl': 350, 'date': date, 'enable_fra': False}, ctx)
                p = r['plan']['primary']
                return p.get('route'), len(loads) - before, p.get('ok')
            s0 = stats()
            r1, n1, ok1 = run()
            c.ok(ok1 and n1 > 0 and stats() == (s0[0] + 1, s0[1]), str((r1, n1, stats(), s0)), 'the first calculation builds the context: it reads the files of the base')
            r2, n2, ok2 = run()
            c.eq((r2 == r1, n2, stats()), (True, 0, (s0[0] + 1, s0[1] + 1)), 'the second reads no file of the base (the context is reused) and gives the same route as the first', what='warm')
            # a file of the base changes (modification time): rebuilt
            base_file = os.path.join(data, 'sia', 'base', 'xx', '2026-10-29', 'points.json')
            st = os.stat(base_file)
            os.utime(base_file, ns=(st.st_atime_ns, st.st_mtime_ns + 5_000_000_000))
            r3, n3, ok3 = run()
            c.ok(ok3 and r3 == r1 and n3 > 0 and stats() == (s0[0] + 2, s0[1] + 1), str((n3, stats())), 'a base file with another modification time: the context is rebuilt, the files are read again')
            # a procedure file added: rebuilt
            os.makedirs(os.path.join(data, 'proc', 'manual'))
            with open(os.path.join(data, 'proc', 'manual', 'LFPO.json'), 'w', encoding='utf-8') as f:
                json.dump({'schema': 1, 'icao': 'LFPO', 'cycle': '2026-10-29', 'procedures': []}, f)
            n4 = run()[1]
            c.ok(n4 > 0 and stats() == (s0[0] + 3, s0[1] + 1), str((n4, stats())), 'a procedure file that appears: rebuilt')
            # the RAD book re-imported: rebuilt
            rp = os.path.join(data, 'route', 'rad.json.gz')
            st = os.stat(rp)
            os.utime(rp, ns=(st.st_atime_ns, st.st_mtime_ns + 5_000_000_000))
            run()
            c.eq(stats(), (s0[0] + 4, s0[1] + 1), 'the RAD book with another modification time: rebuilt', what='rad')
            # a NAT message appears: rebuilt, and the layer is there
            os.makedirs(os.path.join(data, 'sia', 'zones', 'nat'))
            with open(os.path.join(data, 'sia', 'zones', 'nat', 'nat_tracks.json'), 'w', encoding='utf-8') as f:
                json.dump({'tracks': [{'id': 'A', 'route': ['SITET', '51/20', 'KEPAD'], 'east': ['350'], 'west': [], 'from': '2026-11-10T01:00:00Z', 'to': '2026-11-10T08:00:00Z'}]}, f)
            run()
            c.eq(stats(), (s0[0] + 5, s0[1] + 1), 'a NAT file that appears: rebuilt', what='nat')
            key = [k for k in P._CONTEXTS][-1]
            c.eq(P._CONTEXTS[key]['nav'].nat['tracks'], ['A'], 'and the new context carries its tracks', what='nat tracks')
            # the bound: two contexts at most, the oldest leaves
            run('2026-11-11T12:00')
            run('2026-11-12T12:00')
            c.eq((len(P._CONTEXTS), [k[-1].isoformat() for k in P._CONTEXTS]), (2, ['2026-11-11', '2026-11-12']), 'two contexts at most: a third date pushes the oldest out', what='bound')
            built = stats()[0]
            run('2026-11-10T12:00')
            c.eq(stats()[0], built + 1, 'the date that left is rebuilt when it comes back', what='evicted')
            # idle: nothing kept past its idle time
            keep = P.IDLE_S
            P.IDLE_S = -1
            try:
                run('2026-11-10T12:00')
            finally:
                P.IDLE_S = keep
            c.eq(stats()[0], built + 2, 'a context idle for longer than IDLE_S is dropped: the next calculation rebuilds', what='idle')
            run('2026-11-10T12:00')
            P.drop_contexts()
            c.eq(len(P._CONTEXTS), 0, 'drop_contexts empties them', what='drop')
            n9 = run()[1]
            c.ok(n9 > 0, str(n9), 'after the drop the files are read again')
    finally:
        nav_data.load = orig
        RC.ENABLED = True
        P.drop_contexts()


@case('K239', 'Route engine, the reference route ESSB → LEMO (SOG-0161): on a base that holds the Spanish upper network of the user\'s variant (ARVID T424 PPN N857 NOLSA N10 BAN N857 HIJ N10 SVL), the plan is found in under 10 s, mostly controlled, and uses that network; SKIPPED, and says why, while the base lacks it', 'K', static=True,
      rule='Ergonomist 13 Nov 2026 (SOG-0161, the user\'s reference): ESSB → LEMO must give a route whose Spanish part follows ARVID T424 PPN N857 NOLSA N10 BAN N857 HIJ N10 SVL or better, the northern part in FRA when the Swedish points are readable, in under 10 s. The case runs on the workstation\'s real base (E:/DEFA/data, or DEFA_DATA) read-only, never on invented data, and is SKIPPED, with the missing segments named, as long as the zone of Spain does not hold the five segments of the variant (rebuild Spain with the personal-use box: ENAIRE): never red because of the user\'s data. When the data is there it is a real target: measured on 13 Nov with the base of 29 Oct the plan is found (65 % controlled, 22 % incomplete, 13 % fallback) in 14 s cold by `… DEMIR N872 MEDIL … UM728 KOTAP J18 VEROS G54 … L27 BLN DCT LEMO`, without T424 nor N857: it is a known failure (cases/known_failures.py) until the intermediate points on the great circle and the speed are done')
def k239(c):
    import glob
    import json
    import os
    import time
    root = os.environ.get('DEFA_DATA', 'E:/DEFA/data')
    segs = set()
    for f in glob.glob(os.path.join(root, 'sia', 'base', '*', '*', 'airways.json')):
        try:
            with open(f, encoding='utf-8') as fh:
                doc = json.load(fh)
        except (OSError, ValueError):
            continue
        for w in doc.get('data') or []:
            if isinstance(w, dict) and isinstance(w.get('a'), dict) and isinstance(w.get('b'), dict):
                segs.add((str(w.get('route')), frozenset((str(w['a'].get('id')), str(w['b'].get('id'))))))
    variant = [('T424', 'ARVID', 'PPN'), ('N857', 'PPN', 'NOLSA'), ('N10', 'NOLSA', 'BAN'), ('N857', 'BAN', 'HIJ'), ('N10', 'HIJ', 'SVL')]
    if not os.path.isfile(os.path.join(root, 'route', 'rad.json.gz')) or not segs:
        c.skip(f'no real base with the RAD at {root} (DEFA_DATA): the reference route is not run')
    missing = [f'{r} {a}–{b}' for r, a, b in variant if (r, frozenset((a, b))) not in segs]
    if missing:
        c.skip('the base of this workstation lacks the segments of the user\'s variant (' + ', '.join(missing) + '): rebuild Spain with the personal-use box (ENAIRE); the reference route is not run')
    RJ = _regen()
    fn = RJ.REGISTRY[('route', 'compute')][0]
    started = time.perf_counter()
    r = fn(RJ.Job('route', 'compute', {}, author='TST'), {'dep': 'ESSB', 'arr': 'LEMO', 'fl': 350, 'date': '2026-11-13T12:00', 'enable_fra': True}, {'data': root, 'secrets': root})
    seconds = time.perf_counter() - started
    p = r['plan']['primary']
    ctl = p.get('control') or {}
    c.ok(p.get('ok') is True, str(p.get('error')), 'ESSB → LEMO has a route')
    c.ok(seconds < 10, f'{seconds:.1f} s', 'found in under 10 s')
    c.ok((ctl.get('controlled_pct') or 0) >= 65, str(ctl.get('controlled_pct')), 'at least 65 % of the distance controlled (the figure of 10 Nov, never to fall)')
    c.ok(any(w in str(p.get('route')).split() for w in ('T424', 'N857')), str(p.get('route'))[:200], 'the route uses the Spanish upper network of the variant (T424 or N857)')


@case('K241', 'Route engine, an aerodrome with no SID (STAR) read climbs (descends) freely on its DCT connector (SOG-0161): the search, the vertical profile and the control agree, and the connector is a « fallback » that says so; with a SID read nothing changes', 'K', static=True,
      rule='Ergonomist 13 Nov 2026 (SOG-0161, EGLL → KJFK and KJFK → EGLL): the high routes start at 18 000 / 24 500 ft and an aerodrome with no SID read joins them by a DCT connector: the climb the SID would make is not modelled, so no altitude-feasible path existed and the search walked its whole state space to the 6 s budget (EGLL → KJFK on the real base: 40 s, then no route). Without a SID read the departure may start at any altitude up to the cruise level after the connector, and without a STAR read the arrival connector may lose any altitude (`free_departure`, `free_arrival` in the search; the same in `flight_profile.build` so the control does not refuse what the search found); the connector is « fallback » (« montée / descente supposée libre »), like every connector without a procedure. Invented bench: one airway chain whose lower limit is 18 000 ft, the first node 28 NM from the aerodrome. Measured on the real base from the form of the Fuel screen: EGLL → KJFK 1.6 s (NAT H), KJFK → EGLL 2.7 s, ESSB → LEMO 8.0 s cold and 1.3 s warm')
def k241(c):
    import gzip
    import json
    import os
    import tempfile
    RJ = _regen()
    import route_fixture as RF
    from route_engine import import_books as I
    fn = RJ.REGISTRY[('route', 'compute')][0]
    pt = lambda i, lat, lon: {'id': i, 'type': 'ICAO', 'lat': lat, 'lon': lon}
    nodes = {'N1': (41.0, -73.4), 'N2': (42.0, -72.0), 'N3': (45.0, -60.0), 'N4': (50.0, -40.0), 'N5': (52.0, -20.0), 'N6': (51.8, -5.0), 'N7': (51.5, -1.0)}
    ids = list(nodes)
    ways = [{'route': 'J1', 'a': pt(a, *nodes[a]), 'b': pt(b, *nodes[b]), 'lower': 18000, 'upper': 66000} for a, b in zip(ids, ids[1:])]
    with tempfile.TemporaryDirectory(ignore_cleanup_errors=True) as td:
        data = os.path.join(td, 'data')
        os.makedirs(data)
        RF.make_base(data)
        d = os.path.join(data, 'sia', 'base', 'xx', '2026-10-29')
        for k, v in {'aeroindex': {'fields': ['icao', 'name', 'lat', 'lon', 'elev', 'bearing', 'magVar'], 'rows': [['KJFK', 'NEW YORK', 40.64, -73.78, 13, 0, 0], ['EGLL', 'LONDON', 51.47, -0.45, 83, 0, 0]]},
                     'points': [pt(k, *v) for k, v in nodes.items()], 'navaids': [], 'airways': ways}.items():
            with open(os.path.join(d, k + '.json'), 'w', encoding='utf-8') as f:
                json.dump({'schema': 2, 'zone': 'xx', 'cycle': '2026-10-29', 'kind': k, 'data': v}, f)
        rad = os.path.join(td, 'RAD_2611_v1_0.xlsx')
        RF.write_xlsx(rad, RF.rad_sheets())
        I.write(os.path.join(data, 'route', 'rad.json.gz'), I.merge([], [I.read_book(rad)[1]]))
        with gzip.open(os.path.join(data, 'route', 'fra.json.gz'), 'wt', encoding='utf-8') as f:
            json.dump([], f)
        r = fn(RJ.Job('route', 'compute', {}, author='TST'), {'dep': 'KJFK', 'arr': 'EGLL', 'fl': 370, 'date': '2026-11-10T12:00', 'enable_fra': False, 'sections': False}, {'data': data, 'secrets': td})      # SOG-0396: the subject is the connectors of a whole search; with the sections the permanent gates would make a free route over the ocean (the bench has J1 across it)
        p = r['plan']['primary']
        legs = p.get('legs') or []
        c.ok(p['ok'] and [l['via'] for l in legs][1:-1] == ['J1'] * 6, str((p.get('error'), [l['via'] for l in legs])), 'KJFK → EGLL is found: the first airway node (28 NM) is above the reach of a real climb to 18 000 ft, the connector is free of it (no SID read)')
        c.eq([(l['start']['id'], l['end']['id']) for l in legs][:1] + [(legs[-1]['start']['id'], legs[-1]['end']['id'])], [('KJFK', 'N1'), ('N7', 'EGLL')], 'the connectors are the nearest nodes: KJFK → N1 (28 NM) and N7 → EGLL (21 NM)', what='connectors')
        c.eq({l['control'] for l in legs[:1] + legs[-1:]}, {'fallback'}, 'and they are « fallback » (no SID, no STAR read), never controlled', what='class')


@case('K242', 'VFR sequences carry the kind of aircraft (SOG-0253): `aircraft` = fixed | rotary | both | unknown on an INTERPRETED route reaches sia/vfr/<ICAO>.json; a value that is none of them is refused; a candidate (not interpreted) route or an absent field gives « unknown »', 'K', static=True,
      rule='Ergonomist 13 Nov 2026 (SOG-0253: the VFR view gives the directions of the circuit of the VAC chart, solid for aircraft in black, dashed for helicopters in green): the Map already draws the arrow of a sequence and tells a helicopter point; the compiled VAC data carried the direction (`direction`: forward | both | unknown, interpreted only) but not the kind of aircraft. The interpretation files (tools/report-vfr/interpretations/<ICAO>.json, edited by hand from the chart, traceable) may now say, per route, `aircraft`; vfr_import validates it, writes it for an interpreted route only (like `direction`), « unknown » otherwise; vfr_core carries it on the relations and the geometry. Nothing is read automatically from the drawing and no terrain is entered here: who enters the 28 terrains is the user\'s decision (Q-0050)')
def k242(c):
    import importlib
    import json
    import sys
    sys.path.insert(0, str(ROOT / 'tools'))
    imp = importlib.import_module('vfr_import')
    pt = lambda code, lon: {'code': code, 'coordinates': [lon, 44.8], 'role': 'reporting_point', 'pdfPage': 1}
    route = lambda key, **kw: {'key': key, 'pointCodes': ['AD', 'N', 'NE'], 'sourceText': 'N - NE', 'pdfPage': 1, 'status': 'interpreted', 'direction': 'forward', **kw}

    def run(routes):
        ad = {'icao': 'LFXX', 'status': 'interprété', 'points': [pt('AD', -0.7), pt('N', -0.6), pt('NE', -0.5)], 'routes': routes, 'source': {'file': 'AD-2.LFXX.pdf', 'sha256': 'x', 'airac': '2026-10-29'}}
        p = imp.plan({'schemaVersion': '2.0', 'generatedAt': '2026-11-13T10:00:00+00:00', 'sourceAirac': '2026-10-29', 'aerodromes': [ad]}, '/nonexistent')
        if not p['ok']:
            return p, None
        doc = json.loads(next(v for k, v in p['files'].items() if k.endswith('LFXX.json')))
        return p, doc['routes']
    p, rts = run([route('r1', aircraft='rotary'), route('r2', aircraft='fixed'), route('r3', aircraft='both'), route('r4'), route('r5', status='candidate', aircraft='rotary')])
    c.eq(([r['aircraft'] for r in rts], [r['direction'] for r in rts]) if rts else p.get('errors'), (['rotary', 'fixed', 'both', 'unknown', 'unknown'], ['forward', 'forward', 'forward', 'forward', 'unknown']),
         'an interpreted route keeps its kind (rotary, fixed, both), none given or a candidate route gives « unknown »; the direction works as before', what='written')
    p, rts = run([route('bad', aircraft='jet')])
    c.ok(p['ok'] is False and any('sorte d\'appareil' in e for e in p['errors']), str(p.get('errors')), 'a kind that is none of the four is refused, said with its terrain and route')


@case('K244', 'VFR circuits from the user\'s extractor (SOG-0253): the XML `VfrCircuits` is read as an untrusted input (bounds, no entity, finite numbers, cleaned names), the hand is deduced from the order of the points, a terrain whose PDF changed is obsolete, the upload accepts it by its root and the verb vfr/circuits returns it; nothing is invented, nothing is published', 'K', static=True,
      rule='Ergonomist 13 Nov 2026 (Q-0050: « par défaut, à gauche… je cherche à faire un extracteur de tracés vers du xml »): nobody enters the 28 terrains and no session reads the drawing; the user\'s extractor writes the XML `VfrCircuits` (points in the order of the flight, aircraft, altitude and its reference), deposited by the page in data/local/upload/vfr_circuits.xml; tools/vfr_circuits.py reads it with the bounds said (2 MB, 200 terrains, 20 circuits, 64 points: over, the file is refused), no DOCTYPE / ENTITY, finite coordinates in range, names cleaned, a malformed circuit or point left out and counted; `hand` is deduced from the order (left = counter-clockwise seen from above), unknown when open or under three points; the sha256 of a terrain is compared with the one of the PDF the compilation read: different = obsolete (its circuits are not returned); the Map draws the extracted circuits only (the default left hand is a sentence, never a drawing). Invented example of the bench')
def k244(c):
    import importlib
    import json
    import sys
    import tempfile
    from pathlib import Path
    sys.path.insert(0, str(ROOT / 'tools'))
    V = importlib.import_module('vfr_circuits')
    RJ = _regen()
    sha = lambda ch: ch * 64
    pt = lambda seq, lat, lon, code='': f'<Point seq="{seq}" lat="{lat}" lon="{lon}"' + (f' code="{code}"' if code else '') + '/>'
    left = ''.join(pt(i, la, lo) for i, (la, lo) in enumerate([(48.00, -1.70), (48.00, -1.60), (48.05, -1.60), (48.05, -1.70)], 1))
    right = ''.join(pt(i, la, lo) for i, (la, lo) in enumerate([(48.00, -1.70), (48.05, -1.70), (48.05, -1.60), (48.00, -1.60)], 1))
    shuffled = pt(3, 48.05, -1.60) + pt(1, 48.00, -1.70) + pt(4, 48.05, -1.70) + pt(2, 48.00, -1.60)
    doc = ('<?xml version="1.0" encoding="UTF-8"?><VfrCircuits airac="2610" extractor="my extractor &lt;b&gt;v1&lt;/b&gt;">'
           f'<Aerodrome icao="LFXX" source="AD-2.LFXX.pdf" sha256="{sha("a")}">'
           f'<Circuit id="RWY10-A" runways="10 28" aircraft="fixed" altitudeFt="1000" altitudeRef="AAL" closed="true" status="checked">{left}</Circuit>'
           f'<Circuit id="RWY28-H" runways="28" aircraft="rotary" closed="true">{right}</Circuit>'
           f'<Circuit id="open" runways="10" closed="false">{pt(1, 48.0, -1.7, "N")}{pt(2, 48.1, -1.6, "NE")}</Circuit>'
           f'<Circuit id="by-seq" closed="true">{shuffled}</Circuit>'
           f'<Circuit id="bad-aircraft" aircraft="jet">{left}</Circuit>'
           f'<Circuit id="bad-lat">{pt(1, 91, 0)}{pt(2, 48, 0)}</Circuit>'
           f'<Circuit id="nan" closed="true">{pt(1, "nan", 0)}{pt(2, 48, 0)}{pt(3, 48.1, 0.1)}</Circuit>'
           f'<Circuit id="alt-no-ref" altitudeFt="1000" closed="true">{left}</Circuit></Aerodrome>'
           f'<Aerodrome icao="LFYY" sha256="{sha("b")}"><Circuit closed="true">{left}</Circuit></Aerodrome>'
           f'<Aerodrome icao="LFZZ"><Circuit closed="true">{left}</Circuit></Aerodrome>'
           '<Aerodrome icao="bad"><Circuit/></Aerodrome></VfrCircuits>')
    res, warn = V.parse_bytes(doc.encode('utf-8'), {'LFXX': sha('a'), 'LFYY': sha('c')}.get)
    a = res['aerodromes']
    by = {x['id']: x for x in a['LFXX']['circuits']}
    c.eq((res['airac'], res['extractor'], {k: v['state'] for k, v in a.items()}, res['counts']['obsolete']), ('2610', 'my extractor bv1b', {'LFXX': 'current', 'LFYY': 'obsolete', 'LFZZ': 'unchecked'}, ['LFYY']),
         'the header is read and cleaned; the sha256 of a terrain is compared with the PDF the compilation read: equal = current, different = obsolete, unknown on one side = unchecked', what='head')
    c.eq(([x for x in by], a['LFYY']['circuits']), (['RWY10-A', 'RWY28-H', 'open', 'by-seq', 'alt-no-ref'], []), 'the circuits that are kept (in order); an unknown kind of aircraft, an out-of-range or non-finite coordinate are left out; an obsolete terrain returns none', what='kept')
    c.eq((by['RWY10-A']['hand'], by['RWY28-H']['hand'], by['open']['hand'], by['by-seq']['hand']), ('left', 'right', 'unknown', 'left'),
         'the hand is deduced from the order of the points (counter-clockwise = left); an open circuit gives none; the points are sorted by `seq` first', what='hand')
    c.eq((by['RWY10-A']['aircraft'], by['RWY10-A']['altitude'], by['RWY10-A']['runways'], by['RWY10-A']['status'], by['RWY28-H']['aircraft'], by['RWY28-H']['altitude'], by['open']['points'][0].get('code')),
         ('fixed', {'ft': 1000.0, 'ref': 'AAL'}, ['10', '28'], 'checked', 'rotary', None, 'N'), 'aircraft, altitude with its reference, runways, status and report-point code come through; none given: none (never zero)', what='fields')
    c.eq(by['alt-no-ref']['altitude'], None, 'an altitude without its reference is not kept', what='altitude')
    c.eq(warn, {'aerodromes': 1, 'circuits': 3, 'points': 2, 'altitude': 1}, 'what was left out is counted, never corrected', what='warnings')

    def refused(raw):
        try:
            V.parse_bytes(raw)
            return None
        except V.Refused as e:
            return str(e)
    ad = lambda i: f'<Aerodrome icao="LF{chr(65 + i // 26)}{chr(65 + i % 26)}"><Circuit>{left}</Circuit></Aerodrome>'
    c.eq([bool(refused(x)) for x in (b'', b'<VfrCircuits' + b' ' * (2 * 1024 * 1024), b'<?xml version="1.0"?><!DOCTYPE x [<!ENTITY a "b">]><VfrCircuits/>', b'<Other/>', b'not xml',
                                      ('<VfrCircuits>' + ''.join(ad(i) for i in range(201)) + '</VfrCircuits>').encode(),
                                      ('<VfrCircuits><Aerodrome icao="LFXX">' + f'<Circuit>{left}</Circuit>' * 21 + '</Aerodrome></VfrCircuits>').encode(),
                                      ('<VfrCircuits><Aerodrome icao="LFXX"><Circuit>' + pt(1, 1, 1) * 65 + '</Circuit></Aerodrome></VfrCircuits>').encode())], [True] * 8,
         'refused whole, said: empty, over 2 MB, a DOCTYPE or ENTITY, another root, not XML, 201 terrains, 21 circuits, 65 points', what='refused')
    c.eq(refused(('<VfrCircuits>' + ''.join(ad(i) for i in range(200)) + '</VfrCircuits>').encode()), None, 'and 200 terrains are fine (the bound is the bound)', what='bound')
    # the entity guard is BY CONSTRUCTION (the parser itself), not only a search in the bytes: another encoding would hide the word from a byte search
    hostile = '<?xml version="1.0" encoding="UTF-16"?><!DOCTYPE a [<!ENTITY b "cc">]><VfrCircuits airac="2610" extractor="&b;"/>'
    c.eq([bool(refused(x)) for x in (hostile.encode('utf-16'), b'\xff\xfe' + hostile.encode('utf-16-le'), hostile.encode('utf-16-le'), '<?xml version="1.0" encoding="ISO-8859-1"?><VfrCircuits/>'.encode())], [True] * 4,
         'a file that is not UTF-8 (UTF-16 with or without a mark, another declared encoding) is refused: a DOCTYPE written in it would not be seen by a search in the bytes', what='encoding')
    c.eq([refused(b'<VfrCircuits>' + b'<a/>' * 300000 + b'</VfrCircuits>'), refused('<?xml version="1.0" encoding="cp037"?><VfrCircuits/>'.encode('cp037')), refused(b'<VfrCircuits><a></VfrCircuits>')],
         ['trop d’éléments', 'XML illisible', 'XML illisible'],
         'the tree is built by the parser and the elements are counted AS IT READS (a 1.2 MB file of « <a/> » is refused at the bound, not after building 300 000 elements); an encoding the parser cannot read or a broken file is « XML illisible », never an exception', what='elements')
    was = V._DANGER
