        (pkg / 'html' / 'eAIP' / 'EG-AD-2.EGXX-en-GB.html').write_text('<html><head><meta name="EM.effectiveDateStart" content="2026-10-29"/></head><body>' + row + '</body></html>', encoding='utf-8')
