    legs = lambda *alts: [dict(via='T1', kind='AIRWAY', source_zone='ch', start={'id': f'P{n}'}, end={'id': f'P{n + 1}'}, altitude_start_ft=a, altitude_end_ft=b) for n, (a, b) in enumerate(alts)]
    fl = {'ch': 195}
