        run = lambda **extra: PL.compute(V.to_request(dict({'action': 'compute', 'adep': 'LFPO', 'adest': 'EIDW', 'date': '2026-11-09T12:00', 'enable_fra': False, 'speed_kt': 200, 'alternatives': False}, **extra)), data, rad_gz, None)['primary']
        no_level = run()
